import requests

# Try searching for the study by trying different known patterns for academic articles
# Let me try to find it through ResearchGate or other academic platforms
platforms = [
    'https://www.researchgate.net/search?query=Hafnia+alvei+HA4597',
    'https://scholar.google.com/scholar?q=Hafnia+alvei+HA4597',
    'https://www.semanticscholar.org/search?q=Hafnia+alvei+HA4597'
]

for platform in platforms:
    try:
        print(f'Trying: {platform}')
        response = requests.get(platform, headers={'User-Agent': 'Mozilla/5.0'}, timeout=5)

        if response.status_code == 200:
            # Look for the study title
            if 'The Probiotic Strain H. alvei HA4597' in response.text:
                print('  FOUND THE STUDY!')
                # Extract any PMC or DOI information
                import re
                pmc_pattern = r'PMC(\d+)'
                doi_pattern = r'10\.\d+/\S+'

                pmc_matches = re.findall(pmc_pattern, response.text)
                doi_matches = re.findall(doi_pattern, response.text)

                if pmc_matches:
                    print(f'  PMC ID found: PMC{pmc_matches[0]}')
                if doi_matches:
                    print(f'  DOI found: {doi_matches[0]}')
                break
            else:
                print('  Study not found on this platform')
        else:
            print(f'  Failed to access: {response.status_code}')
    except Exception as e:
        print(f'  Error: {e}')
