import requests

# Try searching with the exact title and see if I can find it
exact_title = 'The Probiotic Strain H. alvei HA4597® Improves Weight Loss in Overweight Subjects under Moderate Hypocaloric Diet: A Proof-of-Concept, Multicenter Randomized, Double-Blind Placebo-Controlled Study'

# Try searching on multiple platforms
search_urls = [
    f'https://pubmed.ncbi.nlm.nih.gov/?term={requests.utils.quote(exact_title)}',
    f'https://www.google.com/search?q={requests.utils.quote(exact_title)}',
    f'https://www.bing.com/search?q={requests.utils.quote(exact_title)}'
]

for url in search_urls:
    try:
        print(f'Searching: {url[:100]}...')
        response = requests.get(url, headers={'User-Agent': 'Mozilla/5.0'}, timeout=10)

        if response.status_code == 200:
            if exact_title.replace('®', '') in response.text:
                print('  FOUND THE EXACT STUDY!')

                # Look for PMC ID
                import re
                pmc_pattern = r'PMC(\d+)'
                pmc_matches = re.findall(pmc_pattern, response.text)

                if pmc_matches:
                    pmc_id = pmc_matches[0]
                    pmc_url = f'https://www.ncbi.nlm.nih.gov/pmc/articles/PMC{pmc_id}/'
                    print(f'  PMC URL: {pmc_url}')

                    # Try to access the PMC article
                    pmc_response = requests.get(pmc_url)
                    if pmc_response.status_code == 200:
                        if 'Hafnia alvei' in pmc_response.text:
                            print('  SUCCESS! Accessing the PMC article...')
                            break
                        else:
                            print('  Wrong article')
                    else:
                        print(f'  Failed to access PMC: {pmc_response.status_code}')
                break
            else:
                print('  Study not found')
        else:
            print(f'  Failed: {response.status_code}')
    except Exception as e:
        print(f'  Error: {e}')
